import { Upload, UploadProps } from "@arco-design/web-react";
import { action, computed, observable, makeObservable } from "mobx";
import _ from 'lodash';
import { getUuid } from "@/utils";

export default class Store {
    @observable list: UploadProps['fileList'] = [];

    constructor() {
        makeObservable(this);
    }

    @computed get value(): string[]{

        return this.list.map((o) => o.url).filter((url) => url);
    }

    @observable visible = false;
    // 外部图片链接
    @action setVisible = (bool) => {
        this.visible = bool;
    }

    // 图片列表
    @observable listVisible = false;
    @action setListVisible = (bool) => {
        this.listVisible = bool;
    }

    @observable url = "";
    @action setUrl = (url) => {
        this.url = url;
    }

    @action
    setList = (list: UploadProps['fileList']) => {
        console.log('setList', list);
        this.list = list.map(o => {
            if(!o.url && o.response){
                const res: any = o.response || {};
                if(res.code === 0 && res.data){
                    _.assign(o, res.data);
                }else {
                    o.status = 'error';
                }
            }else if(o.status === 'uploading'){
                o.percent = 50;
            }

            return o;
        });
    }


    // 添加图片
    addFileUrl = (url: string) => {
        this.setList([
            ...this.list,
            {
                uid: getUuid(),
                url: url,
                status: 'done'
            }
        ])
    }

    handlePaste(event) {
        // 获取粘贴的数据
        var items = (event.clipboardData || event.originalEvent.clipboardData).items;
        
        // 遍历粘贴的内容
        for (var i = 0; i < items.length; i++) {
            // 检查是否为图像类型
            if (items[i].type.indexOf("image") !== -1) {
                // 获取图像数据
                var blob = items[i].getAsFile();
                
                console.log('blod', blob);
            }
        }
    }
}