import { jsonItem } from "./json";

/**
 * 流程名称
 */
export enum ModeType {
    api = "api",
    traverse = "traverse",
    filter = 'filter',
}

export enum MethodType {
    'GET' = "GET",
    'POST' = "POST",
    'PUT' = "PUT",
    "DELETE" = "DELETE",
    // "HEAD" = "HEAD",
}

export interface ObjectListProps {
    id: string;
    type: string;
    path: string;
    key: string;
    data: any;
    value?: string;
    children?: ObjectListProps[]
}


export interface ConditionsResult {
	nodes: {
        id: string,
        data: any;
        sort: number;
        // 逻辑 结束节点
        endNode: string;
    }[]
	edges: {
        source: string;
        target: string;
        // 是否禁止删除
        notDel: boolean;
    }[];
}

interface FlowBaseNodeData {
    node_name: string;
    node_conditions?: ConditionsResult;
    // conditions?: ConditionsResult;
}

/**
 * @zh api 节点参数
 */
export interface FlowApiDataProps extends FlowBaseNodeData{
    body: JSONSchema;
    method: MethodType;
    url: string;
    query: jsonItem[];
    headers: jsonItem[];
    response: {
        data: JSONSchema,
        headers: Record<string, any>
    }
}

/**
 * @zh filter 节点参数
 */
export interface FlowFilterDataProps extends FlowBaseNodeData{
    data: string;
    length?: number;
    type?: 'auto' | 'select' | 'last';
    result: JSONSchema;
}

/**
 * @zh traverse 节点参数
 */
export interface FlowTraverseDataProps extends FlowBaseNodeData{
    data: string;
    result: JSONSchema;
}

/**
 * 流程输入参数
 */
export interface FlowToParamItem {
    // 字段名 Field
    name: string;
    // 参数值（默认值）
    value: any;
    // 字段名称
    label: any;
    // 是否必填
    required?: boolean;
}

/**
 * 流程输出参数
 */
export interface FlowOutParamItem {
        // 字段名 Field
        name: string;
        // 参数值（默认值）
        value: any;
        // 字段名称
        label: any;
}
export interface FlowPageProps {
    /**
     * @zh 流程输入参数
     */
    toParams: FlowToParamItem[];
    /**
     * @zh 流程输出参数
     */
    outParams: FlowOutParamItem[];
}



interface PositionProps {
	x: Number;
	y: Number;
}

/**
 * 连接线节点
 */
export interface ApiEdgeListItem {
    id: string;
    source: string;
    target: string;
}

export interface ApiNode_Api {
    id: string;
    modeType: ModeType.api;
    data: FlowApiDataProps;
}
interface ApiNode_Filter {
    modeType: ModeType.filter;
    data: FlowFilterDataProps;
}
interface ApiNode_Traverse {
    modeType: ModeType.traverse;
    data: FlowTraverseDataProps;
}

type ApiNode = ApiNode_Api | ApiNode_Filter | ApiNode_Traverse;

/**
 * node 节点类型
 */
export type ApiNodeListItem = {
	id: string;
	position: PositionProps;
} & ApiNode;

export interface ApiFindFlowDocsResultDataItem {
    _id: string;
    createdAt: string;
    updatedAt: string;
    edgeList: ApiEdgeListItem[];
    nodeList: ApiNodeListItem[];
    page: FlowPageProps;
}

export interface ApiFindFlowDocsResult {
    data: ApiFindFlowDocsResultDataItem[];
    result: boolean;
}

export interface FlowFormProps {
    /**
     * @zh 流程名称
     */
    name: string;
    /**
     * @zh 流程说明
     */
    description: string;
}


/**
 * flow 保存的数据结构
 */
export interface ElementDataProps {
    form: FlowFormProps;
    page?: FlowPageProps;
    nodeList?: ApiNodeListItem[];
    edgeList?: ApiEdgeListItem[];
}