import React, { useEffect, useMemo, useState } from "react";
import store from './store';
import { Image, Button, Modal, Message, Space, Tag, Skeleton, Spin, ImageProps, Grid } from "@arco-design/web-react";
import styles from '../index.module.less';
import { useObserver } from "mobx-react-lite";
import { IconEye } from "@arco-design/web-react/icon";

interface ImageItemProps extends ImageProps {

}
const ImageItem = (props: ImageItemProps) => {

    const [visible, setVisible] = useState<boolean>(false);

    return <Image
        {...props}
        preview={visible}
        src={`${props.src}?x-oss-process=image/auto-orient,1/resize,m_lfit,w_300/quality,q_90`}
        loader={true}
        actions={[
            <Button
                key="view"
                type="primary"
                icon={<IconEye />}
                onClick={() => setVisible(true)}
            >
            </Button>
        ]}
        previewProps={{
            visible: visible,
            onVisibleChange: setVisible,
            src: props.src
        }}
    />
}

interface IndexProps {
    onImage: (url: string) => void;
}
const Index = ({ onImage }: IndexProps) => {

    useState(() => {
        store.init();
    })

    return useObserver(() => {

        const { tagId, setTagId } = store;

        return (
            <div className={styles.imageList}>
                <Space size="mini">
                    <Tag
                        checked={!tagId}
                        checkable
                        onCheck={() => {
                            setTagId("")
                        }}
                        color='arcoblue'
                    >
                        全部
                    </Tag>
                    {store.tags.map((o) => {
                        return (
                            <Tag key={o.id}
                                checked={o.id === tagId}
                                checkable
                                onCheck={() => {
                                    setTagId(o.id)
                                }}
                                color='arcoblue'
                            >
                                {o.name}
                            </Tag>
                        )
                    })}
                </Space>
                <Spin loading={store.loading}>
                    <Grid.Row gutter={[20,20]} >
                        {store.list.map((o) => {
                            return (
                                <Grid.Col span={6} key={o.id}>
                                    <ImageItem
                                        className={styles['col-item']}
                                        src={o.url}
                                        onClick={() => {
                                            onImage(o.url);
                                        }}
                                    />
                                </Grid.Col>
                            )
                        })}
                    </Grid.Row>
                </Spin>
            </div>
        )
    })
}

export default Index;