import { MonacoJSONEditor, MonacoJsonProps } from "@/components/MonacoEditor";
import { Button, Divider, Grid, Message, Modal, Space, Typography } from "@arco-design/web-react";
import { IconCodeBlock, IconLink } from "@arco-design/web-react/icon";
import { HTMLProps, useCallback, useEffect, useMemo, useState } from "react";
import { MyErrorBoundary } from "..";
import { SchemaForm } from "@/components/schema";
import { delayedFunction } from "@/utils";

export interface EditFunctionProps extends Omit<MonacoJsonProps, 'type'> {
    showForm?: boolean; // 是否显示表单
    notModel?: boolean;
    title?: string;
    divProps?: HTMLProps<HTMLDivElement>
}

function EditSchema({ showForm, title, notModel, divProps, ...props }: EditFunctionProps) {

    const [visible, setVisible] = useState<boolean>(false);
    const [value, setValue] = useState<any>(props.value);

    const onChangeValue: any = useCallback(delayedFunction((val) => {
        if(notModel && props.onChange) props.onChange(val);
        else setValue(val);
    }), [])

    useEffect(() => {
        setValue(props.value);
    }, [props.value])


    const content = useMemo(() => {

        if(showForm){
            return (
                <Grid.Row>
                    <Grid.Col span={16}>
                        <MonacoJSONEditor
                            value={value}
                            type="schema"
                            selectionVariable
                            onChange={onChangeValue}
                        />
                    </Grid.Col>
                    <Grid.Col span={8} style={{ paddingLeft: 10 }}>
                        <MyErrorBoundary>
                            <SchemaForm
                                style={{ boxSizing: 'border-box', height: 300, overflowY: 'scroll', overflowX: 'hidden' }}
                                layout="vertical"
                                schema={value}
                                generagteProps={{
                                    cols: 24
                                }}
                            />
                        </MyErrorBoundary>
                    </Grid.Col>
                </Grid.Row>
            )
        }
        return (
            <MonacoJSONEditor
                value={value}
                type="schema"
                selectionVariable
                onChange={onChangeValue}
            />
        )
    },[props, value])

    if(notModel) return content;

    return (
        <div {...divProps}>
            <Button shape='round' type='primary' icon={<IconCodeBlock />}
                onClick={() => {
                    setVisible(true)
                }}
            >
                编辑
            </Button>
            <Modal visible={visible}
                title={title || "Schema编辑"}
                focusLock={false}
                style={{ width: showForm ? '80vw' : 800 }}
                onCancel={() => {
                    setVisible(false)
                }}
                onConfirm={() => {
                    if (props.onChange) {
                        props.onChange(value)
                        setVisible(false);
                    } else {
                        setVisible(false);
                    }
                }}
            >
                {content}
            </Modal>
        </div>
    )
}

export default EditSchema;