import React, { useRef, useCallback, memo, useMemo, useContext, useEffect, useState } from 'react';
import styles from './index.module.less';
import Store from '../store';
import { useObserver } from 'mobx-react-lite';
import { Button } from '@arco-design/web-react';
import { toJS, runInAction } from 'mobx';
import { FormBusinessContext } from "@/components/contexts/FormBusinessContext";
import { DropDragView, DropView, moduleStore } from "react-converter-code";


interface ContentProps {
  store: Store;
}

interface CustomBusinessContextProps {
  store: Store;
  uid: string;
}

const CustomBusinessContext = ({ store, uid }: CustomBusinessContextProps) => {
  const value = useContext(FormBusinessContext);
  useEffect(() => {
    runInAction(() => {
      store.formBusiness[uid] = value;
    })
  },[value])
  return null;
}
/**
 * 页面内容区域
 * @param width 1200
 * @param height 800
 */
export default memo(({ store }: ContentProps) => {
  return useObserver(() => {


    const children = useMemo(() => {
      // console.log('nodeList', toJS(store.list))
      const getElementList = (list) => {
        if(!list || list.length === 0) return null;
        return list.map((o) => {
          const { extraInfo, render } = moduleStore.elements.get(o.key);
          if(extraInfo && extraInfo.portal){
            if(!store.mapStore.has(o.id)){
              store.addMapStore(o.id, o)
            }
            const mapStore = store.mapStore.get(o.id);
            const Element = render;
            return (
              <Element key={o.id} {...mapStore.domProps}>
                <DropDragView
                  key={o.id}
                  pageStore={store as any}
                  contentData={store.contentData}
                  item={o}
                >
                  {getElementList(o.children)}
                </DropDragView>
                <CustomBusinessContext store={store} uid={o.id} />
              </Element>
            )
          }

          return (
            <React.Fragment key={o.id}>
              <DropDragView
                pageStore={store as any}
                contentData={store.contentData}
                item={o}
              >
                {getElementList(o.children)}
              </DropDragView>
              <CustomBusinessContext store={store} uid={o.id} />
            </React.Fragment>
          );
        });
      }
      return getElementList(store.nodeList);
    }, [store.list, store.page]);


    const dropStyle = useMemo(() => {
      return {
        // backgroundColor: store.page.backgroundColor,
        // backgroundImage: 'none',
        ...store.page.style
      } as React.CSSProperties
    },[store.page.style])

    return (
      <DropView store={store as any} style={dropStyle} className={store.page.className}>
        {children}
      </DropView>
    );
  });
});
