import React, { useEffect, useState, useMemo } from 'react';
import * as monaco from 'monaco-editor';
import Store from '../store';
import classnames from 'classnames';
import { Button, Message, Image } from '@arco-design/web-react';
import { IconPen } from '@arco-design/web-react/icon';
import { getUuid } from '@/utils';
import { useObserver } from 'mobx-react-lite';
import fileStore from "@/store/file";
import styles from './index.module.less';

/**
 * 创建react 工作区
 * https://www.swvq.com/boutique/detail/53041
 */
export interface MonacoCodeProps {
    // 是否运行进行变量选择
    selectionVariable?: boolean;
    store: Store;
    value?: string;
    readOnly?: boolean;
    disabled?: boolean;
    onChange?: (data: string) => void;
    // 文件后缀
    ext?: "text" | "json" | "xml" | "html" | "tsx" | "jsx";
}

const MonacoEditor = ({
    store,
    readOnly,
    disabled,
    selectionVariable = false,
    ext = "text",
    onChange,
}: MonacoCodeProps) => {
    const [id] = useState(() => getUuid());


    useEffect(() => {
        // 监听了ext 文件类型的更改

        const onReady = async () => {
            Message.loading({
                id: 'need_update',
                content: '加载资源中，请稍等片刻~',
                duration: 9999999,
            });
            await store.npmInstallZip("terse_node_modules");
            Message.success({
                id: 'need_update',
                content: '加载成功',
            });
            store.monacoInstance = monaco.editor.create(document.getElementById(id), {
                value: "",
                automaticLayout: true,
                contextmenu: false,
                suggestOnTriggerCharacters: true,
            });

            if (store.uri) {
                store.openFile(store.uri);
            }
            store.monacoInstance.onDidChangeModelContent(() => {
                const value = store.monacoInstance.getValue();
                store.setData(value);
                if (onChange) {
                    onChange(value);
                }
            });
            var editorService = store.monacoInstance._codeEditorService;
            var openEditorBase = editorService.openCodeEditor.bind(editorService);
            editorService.openCodeEditor = async (input, source) => {
                const result = await openEditorBase(input, source);
                if (result === null) {
                    const range = {
                        startLineNumber: input.options.selection.startLineNumber,
                        endLineNumber: input.options.selection.endLineNumber,
                        startColumn: input.options.selection.startColumn,
                        endColumn: input.options.selection.endColumn
                    };
                    store.openFile(input.resource);
                    if(store.monacoInstance){
                        store.monacoInstance.revealRangeInCenterIfOutsideViewport(range);
                        store.monacoInstance.setPosition({
                            lineNumber: input.options.selection.startLineNumber,
                            column: input.options.selection.startColumn
                        });
                    }
                }
                return result; // always return the base result
            };

        }
        onReady();

        return () => {
            // 重置数据
            store.model = undefined;
            // 销毁实例后，将数据清空
            if (store.monacoInstance) {
                store.monacoInstance.dispose(); //使用完成销毁实例
                store.monacoInstance = undefined;
            }
            // console.log('store.files', store.files)
            // 销毁自定义组件和页面环境
            store.files.map((o) => {
                const model = monaco.editor.getModel(o.uri);
                // console.log('model', model);
                model.dispose(); // 销毁model实例
            })
            store.files = [];
        };
    }, [])

    useEffect(() => {
        if (store.monacoInstance) {
            // editable 是否启用编译器， true = 启用 
            store.monacoInstance.updateOptions({ editable: !disabled });
        }
    }, [disabled])

    return useObserver(() => {


        const fileUrl = useMemo(() => {
            if(store.uri && store.uri.path.startsWith('/public/static')){
                return fileStore.imgMap[store.uri.path.slice(7)];
            }
            return null;
        },[store.uri])

        return (
            <React.Fragment>
                {fileUrl && (
                    <div className="w-full h-full flex items-center justify-center overflow-auto" key="image">
                        <Image src={fileUrl} />
                    </div>
                )}
                <div
                    id={id}
                    className={classnames({
                        'mocaco-editor-dev': true,
                        [styles.none]: Boolean(fileUrl)
                    })}
                ></div>
            </React.Fragment>
        );
    })
};

export default MonacoEditor;
