import React, { HTMLProps, useEffect, useState } from 'react';
import Store from './store';
import Header from './Header';
import Menu from './Menu';
import Canvas from './Canvas';
import Content from './Content';
import Setting, { SettingProps } from './Setting';
import styles from './index.module.less';
import { modulePlatform } from '@/types/module';
import { ResizeBox, Tabs, Typography } from '@arco-design/web-react';
import PageContext from '@/components/contexts/PageContext';
export { default as CustomPageStore } from './store';
import { ConstructorProps } from "react-converter-code";

export interface CustomPageProps extends HTMLProps<HTMLDivElement> {
  store?: Store;
  storeProps?: ConstructorProps;
  settingProps?: SettingProps;
  // 打开页面编辑方法
  openModuleEidt?: (id: string) => void;
}


export default function CustomPage({
  store: cStore, 
  storeProps, 
  settingProps,
  openModuleEidt,
  ...props 
}: CustomPageProps) {
  const [store] = useState(() => cStore || new Store(storeProps));

  useEffect(() => {
    store.openModuleEidt = openModuleEidt;
    const onKeyDown = (event) => {
      // if (event.keyCode === 8) {
      //   // 判断用户是否按下了 delete 键
      //   if(store.selectId){
      //     store.deleteList(store.selectId);
      //   }
      // }
    }
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown)
    }
  },[])


  return (
    <div className={styles.component} {...props}>
      <Header />
      <div className={styles.body}>
        <PageContext.Provider value={{ store: store.contentData as any }}>
        <ResizeBox.SplitGroup
          direction='horizontal'
          style={{ flex: 1, width: "100%" }}
          panes={[
            {
              content:<Menu pageStore={store} />,
              size: '220px',
              min: "100px"
            },
            {
              content: (
                <Canvas scale={100}
                  store={store}
                  onClick={(e) => {
                    store.setSelectId('')
                    e.stopPropagation();
                  }}
                >
                  <Content store={store} />
                </Canvas>
              ),
            },
            {
              content: <Setting pageStore={store} store={store.settingStore} { ...settingProps }/>,
              min: "100px",
              size: '280px'
            }
          ]}
        />
        </PageContext.Provider>
      </div>
    </div>
  );
}

export {
  PageContext,
  Setting,
  Canvas,
  Content,
  Menu,
  Store,
}