import React, { useMemo } from 'react';
import ReactMarkdown, { } from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Image } from "@arco-design/web-react";
import classNames from 'classnames';
import './style.less';
import { getAllQueryParam, getQueryParam } from '@/utils';


const ImageView = (props) => {
    const { alt, src } = props;
    const { w, h, align } = useMemo(() => {
        const data = getAllQueryParam(src);
        return {
            ...data,
            w: Number(data.w) || data.w,
            h: Number(data.h) || data.h,
        } as any
    },[])

    if(align == "center" || align == "right"){
        return (
            <div
                className={classNames({
                    ['c-image-center']: align == "center",
                    ['c-image-right']: align == "right",
                })}
            >
                <Image alt={alt}
                    src={src}
                    style={{ width: w, height: h }}
                />
            </div>
        )
    }
    return (
        <Image alt={alt}
            src={src}
            style={{ width: w, height: h }}
        />
    )
}
const ViewMarkdown = (props: any) => {

    const components = useMemo(() => {
        return {
            img: (props) => {
                return <ImageView key={props.src} {...props} />;
            }
        }
    },[])
    
    return (
        <Image.PreviewGroup>
            <ReactMarkdown
                className='custom-markdown-style'
                remarkPlugins={[remarkGfm]}
                {...props}
                components={components}
            />
        </Image.PreviewGroup>
    )
}

export default ViewMarkdown;