/**
 * 这边定义了饮用的format 插件组（开发模式下使用）
 */
import { createElement } from 'react';
import { Switch, Modal, Select } from "@arco-design/web-react";
import { EditClass, EditFunction, EditFunctionConfig, EditStyle, 
    EditIcon, EditImage,
    MonacoSchemaEditor, JSONList,
    EditorColor, NodeInput, EditSchema, EditReactNode, MonacoJSONEditor,
    EditFunctionNode,
    EditorQuill, Selector, TreeSelector,
    EditImage2, EditSwitch
} from "@/components/custom";
import Translation from '@/components/custom/Translation';
import EditorTable from '@/components/EditorTable';
import Icon from '@/components/Icon';
import { EditMarkdown, ViewMarkdown } from '@/components/markdown';
import Variable from '@/components/custom/Variable';
import EditInputJS from '@/components/custom/EditInputJS';


export const getFormats = () => {

    return {
        "input": Translation,
        // "switch": Switch,
        "switch": EditSwitch,
        "boolean": (props) => createElement(Switch, { checked: props.value, ...props }),
        "multiple": (props) => createElement(Select, { mode: "multiple", allowCreate: true, allowClear: true, ...props }),
        "selector": Selector,
        "treeSelector": TreeSelector,
        "richText": EditorQuill,
        // 数据源配置
        // "lookup": (props) => createElement(Selector, { type: "lookup", ...props }),
        "icon": EditIcon,
        "image": EditImage,
        "iconText": EditIcon, // text 类型下不会进行icon 解析
        "function": (props) => createElement(EditFunction, { isFunction: true, ...props }),
        "js": EditFunction,
        "inputJS": EditInputJS,
        // "function": EditFunctionConfig,
        "variable": Variable,
        "style": EditStyle,
        "class": EditClass,
        "color": EditorColor,
        "nodeInput": NodeInput,
        "editorTable": EditorTable,
        "jsonSchema": EditSchema,
        "json": MonacoJSONEditor,
        "jsonList": JSONList,
        "object": JSONList.JSONEdit,
        "schema": MonacoSchemaEditor,
        "node": EditReactNode,
        "functionNode": EditFunctionNode,
        "editMarkdown": EditMarkdown,
        "markdown": ViewMarkdown
    }
}


export const getMenuFormats = () => {
    
    return {
        "i18n": (props) => createElement(Translation, { isI18n: true, ...props }),
        // "switch": Switch,
        "switch": EditSwitch,
        "boolean": (props) => createElement(Switch, { checked: props.value, ...props }),
        "multiple": (props) => createElement(Select, { mode: "multiple", allowCreate: true, allowClear: true, ...props }),
        "selector": Selector,
        "treeSelector": TreeSelector,
        "icon": EditIcon,
        "image": EditImage,
    }
}