import React, { useEffect, useState, CSSProperties, useImperativeHandle, forwardRef } from 'react';
import * as monaco from 'monaco-editor';
import '../style.less';
import classnames from 'classnames';
import { Button, Tabs } from '@arco-design/web-react';
import {
  jsonToSchema,
  schemaToJSON,
} from '@/utils/schema';
import Store from './store';
import SchemaTable from './component/SchemaTable';
import { useLocalStore } from 'mobx-react-lite';
import { IconPen } from '@arco-design/web-react/icon';
import { ExpressionSelect } from '@/components/custom';

export interface MonacoJSONSchemaProps {
  // 是否运行进行变量选择
  selectionVariable?: boolean;
  value?: JSONSchema;
  readOnly?: boolean;
  onChange?: (data: JSONSchema) => void;
  isExpression?: boolean;
}

const getValue = (defaultValue?: JSONSchema) => {
  const value = defaultValue ? schemaToJSON(defaultValue) : {};
  if (value && Object.keys(value).length) {
    return JSON.stringify(value, null, '\t');
  }
  return `{\n\t\n}`;
};

const MonacoEditor = ({
  value,
  onChange,
  readOnly,
  selectionVariable = false,
  isExpression
}: MonacoJSONSchemaProps, ref) => {
  const [id] = useState(() => `monaco-${Math.random().toString(32)}`);
  const [activeTab, setActiveTab] = useState('json');
  const [error, setError] = useState<boolean>(false);
  const store = useLocalStore(() => new Store());
  // const [full, setFull] = useState<boolean>(false);

  useImperativeHandle(ref, () => {
    return {
      insertText: store.insertText.bind(store),
      store: store,
    }
  },[])

  useEffect(() => {
    if (activeTab !== 'json') return;
    if (
      store.monacoInstance &&
      JSON.stringify(value) === JSON.stringify(store.json)
    ) {
      return;
    }
    const defaultValue = value || { type: 'object', properties: {} };
    store.setJson(defaultValue);
    const monacoValue = getValue(defaultValue);
    if (!store.monacoInstance) {
      store.model = monaco.editor.createModel(
        monacoValue,
        'json',
        monaco.Uri.parse(`${id}.json`)
      );
      store.monacoInstance = monaco.editor.create(
        document.getElementById(id) as HTMLElement,
        {
          model: store.model,
          readOnly: readOnly,
          // value: monacoValue,
          // language: 'json',
        }
      );
      store.monacoInstance.onDidChangeModelContent(() => {
        const value = store.monacoInstance.getValue();
        try {
          const data = JSON.parse(value);
          const schema = jsonToSchema(data, store.json);
          store.setJson(schema);
          if (onChange) {
            onChange(schema);
          }
          setError(false);
        } catch {
          setError(true);
        }
      });
      //   console.log('monaco', store.monacoInstance)
    } else {
      store.monacoInstance.setValue(monacoValue);
    }
    store.monacoInstance.onMouseDown((event) => {
      if (event.event.leftButton) {
        // 记录光标的位置信息
        store.position = store.monacoInstance.getPosition(event.event);
      }
    })
  }, [value]);

  useEffect(() => {
    return () => {
      if (store.monacoInstance) {
        store.monacoInstance.dispose(); // 使用完成销毁实例
        store.model.dispose(); // 销毁model实例
      }
    };
  }, []);

  return (
    <div className="mocaco-json-schema">
      <Tabs
        type="card-gutter"
        activeTab={activeTab}
        onChange={(key) => {
          setActiveTab(key);
          if (key === 'schema') {
            store.init();
          } else if (key === 'json' && onChange) {
            store.monacoInstance.setValue(getValue(store.json));
          }
        }}
      >
        <Tabs.TabPane key="json" title="JSON">
          <div
            id={id}
            className={classnames({
              'mocaco-editor-dev': true,
              // 'mocaco-editor-dev-full': full,
            })}
          ></div>
          {(selectionVariable && activeTab === "json") && (
            <ExpressionSelect
              onChange={({ value }) => {
                store.insertText(value);
              }}
            >
              <Button size="small" className="mocaco-selection-variable" shape='circle' type='primary' icon={<IconPen />} />
            </ExpressionSelect>
          )}
        </Tabs.TabPane>
        {!readOnly && (
          <Tabs.TabPane key="schema" title="Schema" disabled={error}>
            <SchemaTable
              store={store}
              columnKeys={['default', 'description']}
              onChange={() => {
                // console.log('this', store.json);
                if (onChange) onChange({ ...store.json });
              }}
              isExpression={isExpression}
            />
          </Tabs.TabPane>
        )}
      </Tabs>
    </div>
  );
};

export default forwardRef(MonacoEditor);
