import { List, ListProps } from "@arco-design/web-react"
import styles from './index.module.less';
import classnames from 'classnames';
import { useObserver } from "mobx-react-lite";
import Store from './store';
import { toJS } from "mobx";
import { useMemo } from "react";
import { MethodItem, VarItem } from "@/types/expression";

interface VarListProps extends ListProps<VarItem> {
    // 当前选择下标
    $index: number;
    store: Store;
}

interface MethodListProps extends ListProps<MethodItem> {
    // 当前选择下标
    $index: number;
    store: Store;
}

/**
 * @name 变量表达式
 */
export const VarsList = ({
    $index,
    store,
    ...props
}: VarListProps) => {
    
    return useObserver(() => {


        const selected = useMemo(() => {
            //  console.log('selecteds', toJS(store.selecteds))
            return store.selecteds[$index]
        },[store.selecteds])
        // console.log('selected', selected, toJS(store.selecteds));
        return (
            <List
                size="small"
                header='List title'
                bordered
                render={(item, index) => {
                    // 是否已经选中了当前变量
                    const bool = selected && selected.id === item.id
                    const description = item.schema && (item.schema.description || item.schema.title)
                    return (
                        <List.Item 
                            key={item.id}
                            className={classnames({
                                [styles.selected]: bool
                            })}
                            onClick={() => {
                                store.addSelectedVars($index, item);
                            }}
                            onDoubleClick={() => {
                                store.onOk();
                            }}
                        >
                            <div
                                title={item.field}
                                className={classnames('ellipsis', styles.listName)}
                            >{item.field}</div>
                            {description && (
                                <div
                                    key={item.id}
                                    title={description}
                                    className={classnames('ellipsis', styles.listDescription)}
                                >
                                    {description}
                                </div>
                            )}
                        </List.Item>
                    )
                }}
                {...props}
            />
        )
    })
}

/**
 * @name 需要执行的方法
 */
