import { observable, action, makeObservable } from 'mobx';
import { TableColumnProps } from '@arco-design/web-react';
import {
  schemaToList,
} from '@/utils/schema';
import _ from 'lodash';
import { JSONSchemaItemProps } from '@/types/schema';
import { delayedFunction } from '@/utils';
import * as monaco from 'monaco-editor';
class Store {
  @observable visible = false;
  @action
  setVisible = (bool: any) => {
    this.visible = bool;
  };

  record?: JSONSchemaItemProps;

  constructor() {
    makeObservable(this);
  }

  // modal 模型
  model: any;
  // 创建monaco editor 编译器
  monacoInstance: any;
  // 记录最近编辑器的光标位置
  position: any;

  json: JSONSchema = { type: 'object' };
  setJson = (json: JSONSchema = { type: 'object' }) => {
    this.json = json;
    this.setPostions();
  };

  data: JSONSchemaItemProps[] = [];
  setData = () => {
    this.data = schemaToList(this.json, [])?.children || [];
  };

  // 修改内容时记录当前光标位置
  setPostions = delayedFunction(() => {
    if(this.monacoInstance){
      this.position = this.monacoInstance.getPosition();
    }
  }, 300);

  /**
   * monaco编辑器插入
   */
  insertText(text: string){
    if(!this.monacoInstance) return false;
    const position = this.position;
    if(position){
      // 插入数据
      this.monacoInstance.executeEdits("insertData", [{
        range: new monaco.Range(position.lineNumber, position.column, position.lineNumber, position.column),
        text,
      }]);
      // 获取当前插入点的索引
      var index = this.monacoInstance.getModel().getOffsetAt(position);
      // 移动光标到插入数据之后
      this.monacoInstance.setPosition( this.monacoInstance.getModel().getPositionAt(index + text.length));
    }else {
      // 没有坐标直接最后插入
      const value = this.monacoInstance.getValue();
      this.monacoInstance.setValue(`${value}${text}`);
    }
  }

  init = () => {
    this.setData();
  };
}

export default Store;
