import { Card, Avatar, Typography, Space, CardProps, Tag, Menu, Tooltip, Dropdown, Button, Drawer, Divider } from '@arco-design/web-react';
import { IconThumbUp, IconShareInternal, IconMore, IconMoreVertical } from '@arco-design/web-react/icon';
const { Meta } = Card;
import styles from '../style.module.less';
import React, { useEffect, useMemo, useState } from 'react';
import { MyErrorBoundary } from '@/components/custom';
import Store from '../store';
import { addCSS, removeCss } from '@/utils';


interface ItemViewProps extends CardProps {
    item: any;
}

const ItemView = ({ item, ...props }: ItemViewProps) => {

    useEffect(() => {
        const { extraInfo } = item;
        if(extraInfo && extraInfo.cssStr){
            addCSS(extraInfo.cssStr, item.id);
            return () => {
                removeCss(item.id)
            }
        }
    },[])


    const [visible, setVisible] = useState<boolean>(false);

    return (
        <React.Fragment>
            <Card
                className={styles.itemView}
                title={item.nickname || item.name}
                cover={
                    <div className={styles.itemViewCover}
                        onClick={() => setVisible(true)}
                    >
                        <MyErrorBoundary>
                            <img src={item.extraInfo.previewImg} />
                        </MyErrorBoundary>
                    </div>
                }
                actions={[
                    <span>
                        {item.updatedAt}
                    </span>,
                ]}
                {...props}
            >
                {Boolean(item.PublicTagModule) && (
                    <Space size="mini">
                        {item.PublicTagModule.map((o) => {
                            return <Tag key={o.id} size="small">{o.name}</Tag>
                        })}
                    </Space>
                )}
                <Meta
                    avatar={
                        <Space>
                        {/* <Avatar size={24}>A</Avatar> */}
                         <Typography.Text 
                            ellipsis
                            style={{ marginBottom: 0 }}
                        >{item.userId}</Typography.Text>
                        </Space>
                    }
                    // title={item.nickname || item.name}
                    description={item.description || "暂无说明～"}
                />
            </Card>
            {visible && (
                <Drawer
                    visible
                    style={{ width: 1000 }}
                    title={item.nickname || item.name}
                    onCancel={() => {
                        setVisible(false);
                    }}
                    footer={null}
                >
                    <div className={styles.baseView}
                        onClick={() => setVisible(true)}
                    >
                        <MyErrorBoundary>
                            <img src={item.extraInfo.previewImg} />
                        </MyErrorBoundary>
                    </div>
                    <Divider>基础使用</Divider>
                </Drawer>
            )}
        </React.Fragment>
    )
}

export default ItemView;