/**
 * Generates a readable JSON string with comments from a JSON Schema.
 * @param {Object} schema - The JSON Schema.
 * @returns {string} - The formatted JSON string with comments.
 */
export function generateReadableJson(schema: JSONSchema, data: any) {
    function processProperties(properties: JSONSchema['properties'], requiredFields = []) {
      let result = '{\n';
      const keys = Object.keys(properties);
      keys.forEach((key, index) => {
        const item = properties[key];
        const { title, description } = item;
        // const isRequired = requiredFields.includes(key);
        result += `  // ${title || ''}${description? `(${description})` : ''}\n`;
        result += `  "${key}": ${getDefaultValue(key, item)}`;
        if (index < keys.length - 1) {
          result += ',';
        }
        result += '\n';
      });
      result += '}';
      return result;
    }
  
    function getDefaultValue(key: string, item: JSONSchema) {
      switch (item.type) {
        case 'integer':
        case 'number':
          if(typeof data[key] == 'number') return data[key].toString();
          return 0;
        case 'boolean':
          return data[key].toString();
        case 'object':
          return '{}';
        case 'array':
          return '[]';
        default:
          return `"${data[key] || ''}"`;
      }
    }
  
    if (schema.type === 'object' && schema.properties) {
      return processProperties(schema.properties, schema.required);
    }
  
    throw new Error('Unsupported schema type or missing properties.');
}
  
  